parameters.functionCode:
// Compile comprehensive daily productivity summary
const movements = $input.all()[0]?.json || [];
const opportunities = $input.all()[1]?.json || [];
const fixes = $input.all()[2]?.json || [];
const scores = $input.all()[3]?.json || [];

// Calculate totals
const totalMovements = movements.reduce((sum, m) => sum + parseInt(m.count), 0);
const totalOpportunities = opportunities.length;
const totalFixes = fixes.reduce((sum, f) => sum + parseInt(f.count), 0);
const totalScored = scores.reduce((sum, s) => sum + parseInt(s.count), 0);

// Format movement summary
const movementSummary = movements.map(m => 
  `${m.count} items moved to ${m.to_stage}`
).join(', ');

// Format opportunities by type
const opportunitiesByType = {};
opportunities.forEach(o => {
  opportunitiesByType[o.opportunity_type] = (opportunitiesByType[o.opportunity_type] || 0) + 1;
});
const opportunitySummary = Object.entries(opportunitiesByType)
  .map(([type, count]) => `${count} ${type.replace('_', ' ')}`)
  .join(', ');

// Format coherence fixes
const fixSummary = fixes.map(f => 
  `${f.count} ${f.issue_type.replace('_', ' ')} issues fixed`
).join(', ');

// Format task scores
const scoreSummary = scores.map(s => 
  `${s.count} ${s.color_code} priority items`
).join(', ');

// Identify items needing delegation (high priority opportunities)
const needsDelegation = opportunities
  .filter(o => o.confidence_score >= 0.8)
  .slice(0, 3) // Top 3
  .map(o => `• ${o.title} (${o.opportunity_type})`)
  .join('\n');

return {
  total_movements: totalMovements,
  total_opportunities: totalOpportunities,
  total_fixes: totalFixes,
  total_scored: totalScored,
  movement_summary: movementSummary || 'No movements today',
  opportunity_summary: opportunitySummary || 'No new opportunities',
  fix_summary: fixSummary || 'No coherence issues fixed',
  score_summary: scoreSummary || 'No items scored today',
  needs_delegation: needsDelegation || 'None',
  report_date: new Date().toLocaleDateString()
};

